def snowfall(t, every):
    if every == 0:
        return {"A": False, "B": False}
    return {"A": t % every == 0, "B": (t + every // 2) % every == 0}

def reflex_agent(location, snowy, memory, t):
    if snowy:
        return "Shovel"
    return "Right" if location == "A" else "Left"

def model_agent(location, snowy, memory, t):
    memory[location] = t
    if snowy:
        return "Shovel"
    other = "B" if location == "A" else "A"
    if t - memory.get(other, -99) < 4:
        return "Wait"
    return "Right" if location == "A" else "Left"

def simulate(agent, steps=10, every=0):
    world = {"A": True, "B": True}
    location, score, memory = "A", 0, {}
    for t in range(1, steps + 1):
        action = agent(location, world[location], memory, t)
        if action == "Shovel":
            world[location] = False
            score += 10
        elif action != "Wait":
            location = "B" if action == "Right" else "A"
            score -= 1
        score -= sum(world.values())
        for door, falls in snowfall(t, every).items():
            world[door] = world[door] or falls
        print(f"t={t:<2} {action:<6} now at {location}  score={score}")
    return score

print("reflex:", simulate(reflex_agent, STEPS, EVERY))
print("model :", simulate(model_agent, STEPS, EVERY))

