graph = {}
for (a, b), km in roads.items():
    graph.setdefault(a, []).append((b, km))
    graph.setdefault(b, []).append((a, km))

def priority(mode, g, city, weight):
    if mode == "ucs":
        return g
    if mode == "greedy":
        return weight * h[city]
    return g + weight * h[city]

def search(start, goal, mode="astar", weight=1.0):
    frontier = [(priority(mode, 0, start, weight), 0, start, [start])]
    closed = set()
    step = 0
    while frontier:
        f, g, city, path = heapq.heappop(frontier)
        if city in closed:
            continue
        closed.add(city)
        step += 1
        print(f"{step}. expand {city:<10}  g={g:<5} f={f:g}")
        if city == goal:
            print("route:", " -> ".join(path), f"| {g} km | {step} expansions")
            return path, g
        for nxt, km in graph[city]:
            if nxt not in closed:
                g2 = g + km
                heapq.heappush(frontier, (priority(mode, g2, nxt, weight), g2, nxt, path + [nxt]))
    print("no route")

