import math

heights = [2, 4, 7, 9, 8, 5, 3, 6, 11, 15, 14, 10, 6, 8, 12, 13, 18, 20, 17, 12]
seed = SEED

def rand():
    global seed
    seed = seed * 16807 % 2147483647
    return seed / 2147483647

def hill_climb(x):
    steps = 0
    while True:
        best = max([n for n in (x - 1, x + 1) if 0 <= n < len(heights)], key=lambda n: heights[n])
        if heights[best] <= heights[x]:
            print(f"hill climbing: stuck at x={x}, height={heights[x]} after {steps} moves")
            return x
        x = best
        steps += 1

def annealing(x, T, cooling, steps):
    best = x
    for t in range(steps):
        n = x + (1 if rand() < 0.5 else -1)
        if n < 0 or n >= len(heights):
            continue
        dE = heights[n] - heights[x]
        if dE > 0 or rand() < math.exp(dE / T):
            x = n
        if heights[x] > heights[best]:
            best = x
        if t % 50 == 0:
            print(f"t={t:<4} T={T:6.2f}  x={x:<2} h={heights[x]}")
        T = max(T * cooling, 0.01)
    print(f"annealing: final x={x}, h={heights[x]}, best seen h={heights[best]}")

