rows, cols = 3, 4
wall = {(1, 1)}
terminal = {(0, 3): 1.0, (1, 3): -1.0}
moves = {"^": (-1, 0), "v": (1, 0), "<": (0, -1), ">": (0, 1)}
side = {"^": "<>", "v": "<>", "<": "^v", ">": "^v"}
states = [(r, c) for r in range(rows) for c in range(cols) if (r, c) not in wall]

def step(s, a):
    n = (s[0] + moves[a][0], s[1] + moves[a][1])
    return n if n in states else s

def q_value(V, s, a, gamma, noise):
    outcomes = [(1 - noise, step(s, a))] + [(noise / 2, step(s, b)) for b in side[a]]
    return sum(p * gamma * V[n] for p, n in outcomes)

def value_iteration(gamma, reward, noise, iterations):
    V = {s: 0.0 for s in states}
    for k in range(1, iterations + 1):
        new = {}
        for s in states:
            if s in terminal:
                new[s] = terminal[s]
            else:
                new[s] = reward + max(q_value(V, s, a, gamma, noise) for a in moves)
        delta = max(abs(new[s] - V[s]) for s in states)
        V = new
        if k <= 3 or k == iterations:
            print(f"iteration {k}  (largest change {delta:.4f})")
            for r in range(rows):
                print("  " + "  ".join("  wall" if (r, c) in wall else f"{V[(r, c)]:6.3f}" for c in range(cols)))
    policy = {s: max(moves, key=lambda a: q_value(V, s, a, gamma, noise)) for s in states if s not in terminal}
    print("policy:")
    for r in range(rows):
        print("  " + " ".join("#" if (r, c) in wall else ("+" if terminal.get((r, c), 0) > 0 else "-") if (r, c) in terminal else policy[(r, c)] for c in range(cols)))

