from itertools import product

P_B, P_E = 0.001, 0.002
P_A = {(True, True): 0.95, (True, False): 0.94, (False, True): 0.29, (False, False): 0.001}
P_J = {True: 0.90, False: 0.05}
P_M = {True: 0.70, False: 0.01}

def p(value, prob):
    return prob if value else 1 - prob

def joint(b, e, a, j, m):
    return p(b, P_B) * p(e, P_E) * p(a, P_A[(b, e)]) * p(j, P_J[a]) * p(m, P_M[a])

def ask_burglary(john, mary):
    totals = {True: 0.0, False: 0.0}
    rows = 0
    for b, e, a, j, m in product([True, False], repeat=5):
        if john is not None and j != john:
            continue
        if mary is not None and m != mary:
            continue
        totals[b] += joint(b, e, a, j, m)
        rows += 1
    z = totals[True] + totals[False]
    print(f"summed {rows} rows of the full joint distribution")
    print(f"unnormalised: burglary={totals[True]:.6f}  no burglary={totals[False]:.6f}")
    print(f"normalise: divide both by {z:.6f}")
    print(f"P(Burglary | evidence) = {totals[True] / z:.4f}")

ask_burglary(JOHN, MARY)

T = {"R": {"R": 0.7, "N": 0.3}, "N": {"R": 0.3, "N": 0.7}}
E = {"R": {"U": 0.9, "-": 0.1}, "N": {"U": 0.2, "-": 0.8}}

def forward(obs):
    f = {"R": 0.5, "N": 0.5}
    for t, o in enumerate(obs, 1):
        pred = {s: sum(f[p] * T[p][s] for p in f) for s in f}
        raw = {s: E[s][o] * pred[s] for s in f}
        z = sum(raw.values())
        f = {s: raw[s] / z for s in f}
        print(f"day {t} saw {o}: predict P(rain)={pred['R']:.3f}  update P(rain)={f['R']:.3f}")
    return f

def viterbi(obs):
    m = {s: 0.5 * E[s][obs[0]] for s in T}
    back = []
    for o in obs[1:]:
        prev = m
        m, ptr = {}, {}
        for s in T:
            best = max(T, key=lambda p: prev[p] * T[p][s])
            m[s] = prev[best] * T[best][s] * E[s][o]
            ptr[s] = best
        back.append(ptr)
    last = max(m, key=m.get)
    path = [last]
    for ptr in reversed(back):
        path.append(ptr[path[-1]])
    path.reverse()
    print("most likely weather:", " ".join(path), f"(probability {m[last]:.5f})")

