def train_perceptron(examples, lr, max_epochs=10):
    w, b = [0.0, 0.0], 0.0
    for epoch in range(1, max_epochs + 1):
        errors = 0
        for (x1, x2), y in examples:
            out = 1 if w[0] * x1 + w[1] * x2 + b > 0 else 0
            if out != y:
                errors += 1
                w[0] += lr * (y - out) * x1
                w[1] += lr * (y - out) * x2
                b += lr * (y - out)
        print(f"epoch {epoch}: w=({w[0]:.2f}, {w[1]:.2f}) b={b:.2f} errors={errors}")
        if errors == 0:
            print("converged: every example is classified correctly")
            return w, b
    print("did not converge: no straight line separates these points")
    return w, b

